import { createRootRoute, HeadContent, Link, Outlet, Scripts } from "@tanstack/react-router";

export const Route = createRootRoute({
  head: () => ({
    meta: [{ charSet: "utf-8" }, { title: "Corner shop" }],
    links: [{ rel: "icon", href: "data:," }],
  }),
  component: Root,
});

function Root() {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        <nav>
          <Link to="/">Shop</Link> <Link to="/orders">Orders</Link>
        </nav>
        <Outlet />
        <Scripts />
      </body>
    </html>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { useState } from "react";
import { getMenu, placeOrder } from "../shop";

export const Route = createFileRoute("/")({
  loader: () => getMenu(),
  component: Shop,
});

function Shop() {
  const menu = Route.useLoaderData();
  const [last, setLast] = useState<Awaited<ReturnType<typeof placeOrder>> | null>(null);

  async function buy(item: string) {
    const result = await placeOrder({ data: { item, quantity: 1 } });
    setLast(result);
  }

  return (
    <main>
      <h1>Corner shop</h1>
      <ul>
        {menu.map(({ item, cents, left }) => (
          <li key={item}>
            {item}, ${(cents / 100).toFixed(2)}, {left} in stock{" "}
            <button id={`buy-${item}`} onClick={() => buy(item)}>
              Buy
            </button>
          </li>
        ))}
      </ul>
      <p id="receipt">{last ? JSON.stringify(last) : "Nothing bought yet."}</p>
    </main>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { getOrders } from "../shop";

export const Route = createFileRoute("/orders")({
  loader: () => getOrders(),
  component: Orders,
});

function Orders() {
  const orders = Route.useLoaderData();
  return (
    <main>
      <h1>Orders</h1>
      <ol id="orders">
        {orders.map(o => (
          <li key={o.orderId}>
            {o.quantity} {o.item}, {o.cents} cents{o.loyal ? ", loyalty discount" : ""}
          </li>
        ))}
      </ol>
    </main>
  );
}

