// The worker's entry. It's TanStack Start's handler with two things around it, and neither
// changes what the app does:
//
//  - Static files. In production Cloudflare serves these before a worker runs. Plain workerd
//    has only a directory service, which doesn't set content types, so this does that.
//  - A request ID, for joining the two recordings. Each request logs its ID, which a replay
//    prints, and each response has it in a header, which the browser's recording holds.
import { createStartHandler, defaultStreamHandler } from "@tanstack/react-start/server";

const start = createStartHandler(defaultStreamHandler);

const ContentTypes: Record<string, string> = {
  css: "text/css; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  map: "application/json; charset=utf-8",
};

type Env = { ASSETS: { fetch: typeof fetch } };

async function serve(request: Request, env: Env, pathname: string) {
  if (!pathname.startsWith("/assets/")) return start(request);
  const file = await env.ASSETS.fetch(request);
  const type = ContentTypes[pathname.split(".").pop()!] ?? "application/octet-stream";
  return new Response(file.body, { status: file.status, headers: { "content-type": type } });
}

let requests = 0;

export default {
  async fetch(request: Request, env: Env) {
    const id = ++requests;
    const { pathname, search } = new URL(request.url);
    console.log(`rr-request ${id} ${request.method} ${pathname}${search}`);
    const served = await serve(request, env, pathname);
    const response = new Response(served.body, served);
    response.headers.set("x-rr-request", String(id));
    console.log(`rr-response ${id} ${response.status}`);
    return response;
  },
};

// The server side of the app: a small shop whose state lives in the worker's isolate.
// Everything in a createServerFn handler runs in workerd. During SSR it's a plain call, and
// from the browser it's an RPC. The build removes these handlers from the client bundle.
import { createServerFn } from "@tanstack/react-start";

type Line = { item: string; quantity: number };
type Receipt = { orderId: string; item: string; quantity: number; cents: number; loyal: boolean; left: number };

const cents: Record<string, number> = { espresso: 350, bagel: 275 };
const stock = new Map([
  ["espresso", 7],
  ["bagel", 4],
]);
const orders: Receipt[] = [];

// Every third order is 10% off.
function price({ item, quantity }: Line, previousOrders: number) {
  const full = cents[item] * quantity;
  const loyal = (previousOrders + 1) % 3 === 0;
  const discount = loyal ? Math.round(full * 0.1) : 0;
  return { total: full - discount, loyal };
}

function order(line: Line): Receipt | { soldOut: string } {
  const left = (stock.get(line.item) ?? 0) - line.quantity;
  if (left < 0) return { soldOut: line.item };
  stock.set(line.item, left);
  const { total, loyal } = price(line, orders.length);
  const receipt = { orderId: crypto.randomUUID(), item: line.item, quantity: line.quantity, cents: total, loyal, left };
  orders.push(receipt);
  return receipt;
}

// Called by the home page's loader, so it runs during SSR.
export const getMenu = createServerFn({ method: "GET" }).handler(async () => {
  const menu = [...stock].map(([item, left]) => ({ item, cents: cents[item], left }));
  console.log("menu", JSON.stringify(menu));
  return menu;
});

// Called by the Buy button, after hydration.
export const placeOrder = createServerFn({ method: "POST" })
  .validator((line: Line) => line)
  .handler(async ({ data }) => {
    const result = order(data);
    console.log("order", JSON.stringify(result));
    return result;
  });

// Called by the orders page's loader, which is an RPC when the browser navigates there.
export const getOrders = createServerFn({ method: "GET" }).handler(async () => {
  console.log("orders", orders.length);
  return orders;
});

